WITH matched_keys AS (SELECT order_id FROM order_items EXCEPT ALL SELECT order_id FROM order_items WHERE product_id IS NULL), reconciled AS (SELECT s.* FROM order_items s INNER JOIN matched_keys k ON s.order_id = k.order_id) SELECT product_id, STDDEV_SAMP(unit_price) AS unit_price_stddev, STDDEV_SAMP(unit_price) AS unit_price_stddev_2, SUM(quantity) AS total_quantity FROM reconciled GROUP BY product_id ORDER BY total_quantity DESC NULLS LAST
